    "html": "<section style=\"background:#E3D1BC;color:#3C201D;font-family:Figtree, Arial, sans-serif\"><img src=\"/pitch/skin-laundry/inyeccion.jpg\" alt=\"Tratamiento de medicina estética en Skin Laundry\" style=\"position:absolute;left:1105px;top:0px;width:815px;height:1080px;object-fit:cover;object-position:100% 40%;border-radius:0px;\"><img src=\"/pitch/skin-laundry/logo-negro.png\" alt=\"Skin Laundry\" style=\"position:absolute;left:128px;top:128px;width:340px;height:auto\"><h2 style=\"position:absolute;left:128px;top:380px;width:900px;font-family:Newsreader, Georgia, serif;font-weight:300;font-size:120px;line-height:1.06;letter-spacing:-1.5px;color:inherit\">Fifteen minutes.<br><i>Nobody else.</i></h2><p style=\"position:absolute;left:128px;top:680px;width:640px;font-size:34px;line-height:1.4;font-weight:400;color:#7A5C55;\">El hueco está libre. Ahora toca ocuparlo.</p><p style=\"position:absolute;left:128px;top:960px;width:940px;font-size:22px;line-height:1.4;font-weight:400;color:#7A5C55;letter-spacing:2px;text-transform:uppercase\">Maen Studios × Skin Laundry · Barcelona, noviembre de 2026</p></section>"
